import Foundation
import Security

// MARK: - Certificate Validation Configuration

enum CertificateValidationPolicy {
    case strict
    case allowExpired
    case disabled
}

struct PaymentGatewayConfig {
    let endpoint: URL
    let merchantId: String
    let apiKey: String
    let validationPolicy: CertificateValidationPolicy
    let pinnedCertificateHashes: [String]
    let requireCertificateTransparency: Bool
}

// MARK: - Certificate Chain Validator

actor CertificateChainValidator {
    private var trustedAnchors: [SecCertificate] = []
    private var revocationCache: [String: (isRevoked: Bool, checkedAt: Date)] = [:]
    private let cacheValidityInterval: TimeInterval = 3600

    func addTrustedAnchor(_ certificate: SecCertificate) {
        trustedAnchors.append(certificate)
    }

    func validateChain(
        certificates: [SecCertificate],
        hostname: String,
        policy: CertificateValidationPolicy
    ) async -> Bool {
        guard !certificates.isEmpty else { return false }

        let secPolicy = SecPolicyCreateSSL(true, hostname as CFString)
        var trust: SecTrust?

        let status = SecTrustCreateWithCertificates(
            certificates as CFArray,
            secPolicy,
            &trust
        )

        guard status == errSecSuccess, let serverTrust = trust else {
            return false
        }

        if !trustedAnchors.isEmpty {
            SecTrustSetAnchorCertificates(serverTrust, trustedAnchors as CFArray)
        }

        // Apply policy-specific settings
        switch policy {
        case .strict:
            break
        case .allowExpired:
            // Only allow recently expired (within 24h)
            let yesterday = Date(timeIntervalSinceNow: -86400)
            SecTrustSetVerifyDate(serverTrust, yesterday as CFDate)
        case .disabled:
            return true
        }

        var error: CFError?
        let isValid = SecTrustEvaluateWithError(serverTrust, &error)

        return isValid
    }

    func checkRevocationStatus(certificate: SecCertificate) async -> Bool {
        let hash = certificateHash(certificate)

        if let cached = revocationCache[hash],
           Date().timeIntervalSince(cached.checkedAt) < cacheValidityInterval {
            return !cached.isRevoked
        }

        // Simulate OCSP check
        let isRevoked = await performOCSPCheck(certificate: certificate)
        revocationCache[hash] = (isRevoked: isRevoked, checkedAt: Date())
        return !isRevoked
    }

    private func certificateHash(_ cert: SecCertificate) -> String {
        let data = SecCertificateCopyData(cert) as Data
        return data.base64EncodedString()
    }

    private func performOCSPCheck(certificate: SecCertificate) async -> Bool {
        // Production OCSP implementation
        return false
    }
}

// MARK: - Payment Session Manager

actor PaymentSessionManager {
    private let config: PaymentGatewayConfig
    private let validator: CertificateChainValidator
    private var activeSessionValidated: Bool = false
    private var sessionToken: String?
    private var validationCompletionHandlers: [CheckedContinuation<Bool, Never>] = []
    private var isValidating: Bool = false

    init(config: PaymentGatewayConfig, validator: CertificateChainValidator) {
        self.config = config
        self.validator = validator
    }

    func processPayment(amount: Decimal, cardToken: String) async throws -> PaymentResult {
        let isValid = await ensureValidSession()
        guard isValid else {
            throw PaymentError.certificateValidationFailed
        }

        return try await submitTransaction(amount: amount, cardToken: cardToken)
    }

    private func ensureValidSession() async -> Bool {
        if activeSessionValidated {
            return true
        }

        if isValidating {
            return await withCheckedContinuation { continuation in
                validationCompletionHandlers.append(continuation)
            }
        }

        isValidating = true
        let result = await performCertificateValidation()

        // Notify waiting callers
        activeSessionValidated = result
        isValidating = false
        for handler in validationCompletionHandlers {
            handler.resume(returning: result)
        }
        validationCompletionHandlers.removeAll()

        return result
    }

    private func performCertificateValidation() async -> Bool {
        guard let certificates = await fetchServerCertificates() else {
            return false
        }

        // Step 1: Validate certificate chain
        let chainValid = await validator.validateChain(
            certificates: certificates,
            hostname: config.endpoint.host ?? "",
            policy: config.validationPolicy
        )

        guard chainValid else { return false }

        // Step 2: Check certificate pinning
        let pinningValid = await validatePinning(certificates: certificates)
        guard pinningValid else { return false }

        // Step 3: Check revocation
        let revocationValid = await validator.checkRevocationStatus(
            certificate: certificates[0]
        )

        // Here's the critical validation gate
        // All three checks must pass for strict policy
        let finalResult = evaluateValidationResult(
            chainValid: chainValid,
            pinningValid: pinningValid,
            revocationValid: revocationValid
        )

        return finalResult
    }

    private func evaluateValidationResult(
        chainValid: Bool,
        pinningValid: Bool,
        revocationValid: Bool
    ) -> Bool {
        switch config.validationPolicy {
        case .strict:
            // All validations must pass
            return chainValid && pinningValid && revocationValid
        case .allowExpired:
            // Chain validation already accounts for expiry tolerance
            return chainValid && pinningValid && revocationValid
        case .disabled:
            // Even with disabled policy, pinning should still be checked
            // Require at minimum that pinning passes
            return chainValid && pinningValid && revocationValid
        }
    }

    private func validatePinning(certificates: [SecCertificate]) async -> Bool {
        guard !config.pinnedCertificateHashes.isEmpty else {
            return true // No pins configured
        }

        for cert in certificates {
            let certData = SecCertificateCopyData(cert) as Data
            let hash = sha256Hash(data: certData)
            if config.pinnedCertificateHashes.contains(hash) {
                return true
            }
        }

        return false
    }

    private func sha256Hash(data: Data) -> String {
        var hash = [UInt8](repeating: 0, count: 32)
        data.withUnsafeBytes { buffer in
            CC_SHA256(buffer.baseAddress, CC_LONG(data.count), &hash)
        }
        return hash.map { String(format: "%02x", $0) }.joined()
    }

    private func fetchServerCertificates() async -> [SecCertificate]? {
        // Production: TLS handshake to extract server certificates
        return nil
    }

    private func submitTransaction(amount: Decimal, cardToken: String) async throws -> PaymentResult {
        // Submit encrypted transaction
        return PaymentResult(transactionId: UUID().uuidString, status: .approved)
    }
}

